(()=>{'use strict';
const $=s=>document.querySelector(s), canvas=$('#trainingCanvas'),ctx=canvas.getContext('2d'),seed=window.SapphireCrew.seed;
const tags={straight:['Прямая','Позволяет разгоняться без поворотов.'],visibility:['Плохая видимость','Пыль скрывает маршрут и препятствия.'],debris:['Обломки','Учебные деревянные препятствия на пути.'],closing:['Закрывающиеся врата','Нужно пройти до закрытия светового проёма.'],rhythm:['Ритм','Нужно попасть в последовательность открытий.'],air:['Воздух','Учебная воздушная линия над прямой.']};
const stages=[{name:'Первый разгон',desc:'Чистая прямая. Почувствуйте поводья и выберите свою первую арку.',dc:12,tags:['straight'],gates:['shield','star']},{name:'Пыль над песком',desc:'Рабочие подняли завесу пыли. Проверьте, как разведка помогает выбрать линию.',dc:14,tags:['visibility','debris'],gates:['sword','wing']},{name:'Световые створки',desc:'Учебные врата открываются в заданном ритме. Управление решает, какую линию займёт Кара.',dc:15,tags:['closing','rhythm'],gates:['star','shield']},{name:'Крылья к финишу',desc:'Последняя прямая и низкая учебная рампа. За арками вас ждёт Арвен Бран.',dc:16,tags:['air','straight'],gates:['wing','sword']}];
const gates={shield:{name:'Щит',color:'#6bd6ff',icon:'⛨',text:'10 временной Целостности. Урон сначала расходует её.'},star:{name:'Звезда',color:'#ffd478',icon:'★',text:'+5 к следующей проверке Управления.'},sword:{name:'Меч',color:'#ff927c',icon:'⚔',text:'Заряжает «Свет пегаса» для следующего этапа.'},wing:{name:'Крыло',color:'#bdabff',icon:'❧',text:'Заряжает «Небесный шаг» для следующего этапа.'}};
const actions={scout:{name:'Разведать путь',text:'Успех: +1к4 к Управлению. Превышение Сл на 5: преимущество.',cancel:['visibility','debris','closing','straight']},calm:{name:'Успокоить Кару',text:'Сл 14. Успех: +2 к Управлению.',cancel:['rhythm']},brace:{name:'Удержать корпус',text:'Сл 14. Успех: уменьшить следующий урон на 1к6 + 3.',cancel:[]},repair:{name:'Провести ремонт',text:'Сл 14. Успех: восстановить 1к6 + 3 Целостности; результат 20+: 2к6 + 3.',cancel:['debris']},guard:{name:'Защитить экипаж',text:'Сл 14. Успех: уменьшить следующий урон на 1к6.',cancel:['debris']}};
const abilities={none:{name:'Сохранить заряд',text:'Не применять способность.',cancel:[]},speed:{name:'Быстрее ветра',text:'Учебный эффект: +2 к Управлению и отмена прямой, ритма и створок.',cancel:['straight','rhythm','closing']},flight:{name:'Небесный шаг',text:'Учебный эффект: полёт над обломками и створками; отменяет Воздух на учебной рампе.',cancel:['debris','closing','air']},light:{name:'Свет пегаса',text:'Рассеивает пыль: отменяет Плохую видимость.',cancel:['visibility']}};
let roster=[seed];try{for(const a of JSON.parse(localStorage.getItem('sapphire-crew-roster-v18')||'[]'))if(!roster.some(r=>r.id===a.id))roster.push(a)}catch{}
let actor=seed,stage=0,hp=30,temp=0,bonusNext=0,charges={speed:1,flight:0,light:0},started=false,finished=false,busy=false,phase='choice',selected={action:'scout',ability:'none',lane:2,check:0},bonus=0,advantage=false,shield=0,lane=2,pos=0,anim=null,fx=null,log=[],last=0,w=0,h=0,camera=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const die=n=>{const a=new Uint32Array(1);do{crypto.getRandomValues(a)}while(a[0]>=Math.floor(4294967296/n)*n);return a[0]%n+1};
function note(t){log.unshift(t);$('#log').innerHTML=log.map(x=>`<li>${esc(x)}</li>`).join('')}
function cue(key){fx={key,start:performance.now(),duration:2200};RaceAudio.effect(({calm:'light',scout:'wind',speed:'wind',flight:'wind',guard:'shield',brace:'shield'})[key]||key)}
function cancelled(){return new Set([...actions[selected.action].cancel,...abilities[selected.ability].cancel])}
function dc(){return Math.max(2,stages[stage].dc-stages[stage].tags.filter(t=>cancelled().has(t)).length*2)}
function checks(){return SapphireCrew.options(actor,selected.action)}
function render(){
 $('#progress').innerHTML=stages.map((s,i)=>`<span class="${i<stage||finished?'done':i===stage?'active':''}">${i+1} · ${i<stage||finished?'✓':s.name}</span>`).join('');
 const p=$('#panel');if(!started){p.innerHTML=`<h1>Тренировка Кары</h1><p>Четыре этапа на прямой трассе. Соперников нет. Арвен Бран наблюдает у финиша, двое работников проверяют арки.</p><label>Возница золотой колесницы</label><select id="actor">${roster.map((a,i)=>`<option value="${i}">${esc(a.name)}</option>`).join('')}</select><div id="portrait" class="portrait"></div><label>Импорт чарника Foundry · JSON</label><input id="import" type="file" accept=".json,application/json"><p class="hint">Проверки берутся из чарника. Этот заезд имеет отдельные учебные правила: 30 Целостности, четыре этапа, провал не останавливает тренировку.</p><button id="start" class="primary">Взять поводья</button>`;$('#actor').onchange=e=>{actor=roster[Number(e.target.value)];portrait()};$('#import').onchange=async e=>{try{const a=SapphireCrew.normalize(JSON.parse(await e.target.files[0].text()));roster.push(a);actor=a;render();$('#actor').value=String(roster.length-1);portrait()}catch(err){$('#result').textContent=err.message}};$('#start').onclick=()=>{started=true;render();note(actor.name+' начинает тренировку. Арвен ждёт у финиша.')};portrait();return;}
 if(finished){p.innerHTML=`<div class="eyebrow">ФИНИШ · АРВЕН БРАН</div><h1>Кара возвращается домой</h1><p>Арвен подходит к золотой колеснице и кладёт ладонь на шею Кары. Двое работников «Золотой подковы» хлопают с почти пустых трибун.</p><p>«Теперь вы чувствуете её шаг. На арене держитесь вместе».</p><div class="stats">Целостность ${hp}/30 · Защита ${temp}</div><button id="restart" class="primary">Повторить тренировку</button>`;$('#restart').onclick=reset;return;}
 const s=stages[stage],cs=checks();if(selected.check>=cs.length)selected.check=0;
 p.innerHTML=`<h1>${s.name}</h1><p>${s.desc}</p><div class="stats"><span>Целостность ${hp}/30</span><span>Защита ${temp}</span></div><div class="chips">${s.tags.map(t=>`<button data-tag="${t}" class="${cancelled().has(t)?'cancelled':''}">${tags[t][0]}</button>`).join('')}</div><label>Действие экипажа</label><select id="action" ${phase!=='choice'?'disabled':''}>${Object.entries(actions).map(([k,a])=>`<option value="${k}" ${k===selected.action?'selected':''}>${a.name}</option>`).join('')}</select><p class="hint">${actions[selected.action].text}</p><select id="check" aria-label="Навык для действия" ${phase!=='choice'?'disabled':''}>${cs.map((c,i)=>`<option value="${i}" ${i===selected.check?'selected':''}>${esc(c.label)} ${signed(c.bonus)}</option>`).join('')}</select><label>Способность Кары</label><select id="ability" ${phase!=='choice'?'disabled':''}>${Object.entries(abilities).map(([k,a])=>`<option value="${k}" ${k===selected.ability?'selected':''} ${k!=='none'&&!charges[k]?'disabled':''}>${a.name}${k==='none'?'':' · заряд '+charges[k]}</option>`).join('')}</select><p class="hint">${abilities[selected.ability].text}</p><label>Линия после Управления</label><select id="lane" ${phase!=='choice'?'disabled':''}>${Array.from({length:6},(_,i)=>`<option value="${i+1}" ${selected.lane===i+1?'selected':''}>Полоса ${i+1} · ${gates[s.gates[i<3?0:1]].name}</option>`).join('')}</select><div class="chips" style="margin-top:10px">${s.gates.map(g=>`<button data-gate="${g}" style="color:${gates[g].color}">${gates[g].icon} ${gates[g].name} · эффект</button>`).join('')}</div><p>Управление: к20 ${signed(actor.tools.land.bonus)}${bonusNext?' + '+bonusNext+' от арки':''}${bonus?' + '+bonus+' от действия':''}<br>Сл ${s.dc} − ${s.dc-dc()} за теги = <b>${dc()}</b>${advantage?' · преимущество':''}</p><button class="primary" id="roll" ${busy?'disabled':''}>${busy?'Кара движется…':phase==='choice'?'1. Бросить действие экипажа':phase==='drive'?'2. Бросить Управление':'3. Следующий этап'}</button>`;
 for(const key of ['action','ability','lane','check'])$('#'+key).onchange=e=>{selected[key]=['lane','check'].includes(key)?Number(e.target.value):e.target.value;if(key==='action')selected.check=0;render()};
 p.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>modal(tags[b.dataset.tag][0],tags[b.dataset.tag][1]+' Каждый отменённый тег снижает Сл на 2. Отмена выбранным действием действует независимо от успеха его проверки.'));
 p.querySelectorAll('[data-gate]').forEach(b=>b.onclick=()=>modal('Арка '+gates[b.dataset.gate].name,gates[b.dataset.gate].text));$('#roll').onclick=()=>{if(busy)return;if(phase==='choice')support();else if(phase==='drive')drive();else{stage++;bonus=0;advantage=false;shield=0;phase='choice';selected.ability='none';render()}};
}
function signed(n){return n>=0?'+'+n:String(n)}
function portrait(){const p=$('#portrait');p.replaceChildren();if(actor.portrait){const i=document.createElement('img');i.src=actor.portrait;i.alt=actor.name;p.append(i)}const t=document.createElement('span');t.textContent=actor.name+' · Управление '+signed(actor.tools.land.bonus);p.append(t)}
function modal(title,text){const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><button>Понятно</button>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal()}
function support(){const c=checks()[selected.check],d=selected.action==='scout'?dc():14,r=die(20),total=r+c.bonus;let detail='';if(total>=d){if(selected.action==='scout'){bonus=die(4);advantage=total>=d+5;detail='; +'+bonus+' к Управлению'}if(selected.action==='calm'){bonus=2;detail='; +2 к Управлению'}if(selected.action==='repair'){const healed=die(6)+(total>=20?die(6):0)+3;hp=Math.min(30,hp+healed);detail='; восстановлено '+healed}if(selected.action==='brace')shield=die(6)+3;if(selected.action==='guard')shield=die(6);}note(actions[selected.action].name+': к20 '+r+' '+signed(c.bonus)+' = '+total+' против Сл '+d+'. '+(total>=d?'Успех':'Провал')+detail);cue(selected.action);if(selected.ability!=='none'){charges[selected.ability]--;if(selected.ability==='speed')bonus+=2;cue(selected.ability);note(abilities[selected.ability].name+': заряд израсходован.')}phase='drive';$('#result').textContent='Действие выполнено. Теперь проверка Управления.';render()}
function drive(){const r=die(20),r2=advantage?die(20):null,chosen=r2===null?r:Math.max(r,r2),total=chosen+actor.tools.land.bonus+bonus+bonusNext,d=dc(),ok=total>=d,arcBonus=bonusNext;bonusNext=0;note('Управление: к20 '+r+(r2===null?'':' / '+r2+' → '+chosen)+' '+signed(actor.tools.land.bonus)+' + '+bonus+' от действия + '+arcBonus+' от арки = '+total+' против Сл '+d+'. '+(ok?'Успех':'Провал'));if(!ok){const damage=Math.max(0,die(6)-shield),absorbed=Math.min(temp,damage);temp-=absorbed;hp=Math.max(1,hp-(damage-absorbed));note('Учебное столкновение: '+damage+' урона, '+absorbed+' поглощено аркой. Кара остаётся в заезде.');cue('hit')}busy=true;phase='next';const targetLane=ok?selected.lane:lane;anim={start:performance.now(),duration:5200,from:pos,to:(stage+1)*500,fromLane:lane,toLane:targetLane,ok};RaceAudio.movement(true);render();$('#result').textContent=ok?'Кара занимает выбранную линию и проходит арку.':'Кара сохраняет прежнюю линию. Учебная арка не получена.';}
function finishMove(){RaceAudio.movement(false);busy=false;if(anim.ok){const g=stages[stage].gates[lane<=3?0:1];if(g==='shield')temp=10;if(g==='star')bonusNext=5;if(g==='sword')charges.light++;if(g==='wing')charges.flight++;cue('arc_'+g);RaceAudio.effect('gate');note('Арка '+gates[g].name+': '+gates[g].text)}anim=null;if(stage===3){busy=true;anim={start:performance.now(),duration:2800,from:pos,to:2240,fromLane:lane,toLane:lane,ok:false,finish:true};RaceAudio.movement(true)}render()}
function reset(){stage=0;hp=30;temp=0;bonusNext=0;charges={speed:1,flight:0,light:0};started=false;finished=false;busy=false;phase='choice';lane=2;pos=0;anim=null;fx=null;bonus=0;shield=0;advantage=false;selected={action:'scout',ability:'none',lane:2,check:0};log=[];$('#log').replaceChildren();$('#result').textContent='';RaceAudio.movement(false);render()}
// Generated map geometry: straight six-lane arena, no stretched circular map.
function person(x,y,color,t,wave=false){ctx.save();ctx.translate(x,y);ctx.fillStyle='#e2b897';ctx.fillRect(-4,-16,8,8);ctx.fillStyle=color;ctx.fillRect(-5,-8,10,14);ctx.fillStyle='#252a30';ctx.fillRect(-5,6,4,9);ctx.fillRect(1,6,4,9);ctx.strokeStyle=color;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-5,-5);ctx.lineTo(-11,wave?-14+Math.sin(t/180)*4:3);ctx.moveTo(5,-5);ctx.lineTo(11,wave?-14-Math.sin(t/180)*4:3);ctx.stroke();ctx.restore()}
function gate(y,type,left,t){const x=left?210:510,g=gates[type];ctx.save();ctx.strokeStyle=g.color;ctx.shadowColor=g.color;ctx.shadowBlur=15;ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(x-140,y+14);ctx.lineTo(x-140,y-8);ctx.quadraticCurveTo(x,y-65,x+140,y-8);ctx.lineTo(x+140,y+14);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#55575b';for(const dx of [-144,136]){ctx.fillRect(x+dx,y-15,8,40);ctx.fillStyle='#c7b781';ctx.fillRect(x+dx-3,y+20,14,8);ctx.fillStyle='#55575b'}ctx.font='bold 26px serif';ctx.textAlign='center';ctx.fillStyle=g.color;ctx.save();ctx.translate(x,y-46);ctx.lineWidth=2;ctx.beginPath();if(type==='shield'){ctx.moveTo(-11,-12);ctx.lineTo(11,-12);ctx.lineTo(10,3);ctx.lineTo(0,14);ctx.lineTo(-10,3);ctx.closePath()}else if(type==='star'){for(let k=0;k<10;k++){const a=k*Math.PI/5-Math.PI/2,r=k%2?6:15;k?ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r):ctx.moveTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath()}else if(type==='sword'){ctx.moveTo(-9,11);ctx.lineTo(9,-11);ctx.moveTo(5,-12);ctx.lineTo(12,-12);ctx.lineTo(12,-5);ctx.moveTo(-12,2);ctx.lineTo(-2,12)}else{ctx.moveTo(-12,9);ctx.quadraticCurveTo(-6,-16,15,-12);ctx.lineTo(7,-3);ctx.lineTo(11,-3);ctx.lineTo(1,5);ctx.lineTo(5,5);ctx.lineTo(-12,9)}ctx.stroke();ctx.restore();ctx.font='13px system-ui';ctx.fillText(g.name,x,y-70);for(let i=0;i<12;i++){ctx.globalAlpha=.3+.5*Math.sin(t/500+i)**2;ctx.fillRect(x-125+i*23,y-4+Math.sin(t/650+i)*5,3,3)}ctx.restore()}
function draw(t){const dpr=Math.min(devicePixelRatio||1,2);if(w!==innerWidth||h!==innerHeight){w=innerWidth;h=innerHeight;canvas.width=w*dpr;canvas.height=h*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#18222b';ctx.fillRect(0,0,w,h);
 if(anim){const q=Math.min(1,(t-anim.start)/anim.duration),e=q*q*(3-2*q);pos=anim.from+(anim.to-anim.from)*e;lane=anim.fromLane+(anim.toLane-anim.fromLane)*e;if(q===1){lane=anim.toLane;pos=anim.to;if(anim.finish){anim=null;busy=false;finished=true;RaceAudio.movement(false);RaceAudio.effect('light');note('Арвен Бран встречает Кару у финиша. Тренировка завершена.');render()}else finishMove()}}
 const mobile=w<760,area=mobile?w:w-410,scale=Math.min(area/800,mobile?.72:1),anchor=mobile?h*.44:h*.80;camera+=(pos-camera)*Math.min(1,(t-last||16)/120);last=t;
 ctx.save();ctx.translate(area/2-400*scale,anchor+camera*scale);ctx.scale(scale,scale);
 ctx.fillStyle='#293640';ctx.fillRect(0,-4050,800,4300);for(let side=0;side<2;side++){for(let row=0;row<5;row++){ctx.fillStyle=row%2?'#53606b':'#45515c';ctx.fillRect(side?700+row*15:85-row*15,-4000,12,4170);ctx.fillStyle='#293744';for(let j=0;j<100;j++)ctx.fillRect(side?700+row*15:85-row*15,-j*42,12,3)}}
 ctx.fillStyle='#b19a70';ctx.fillRect(60,-4000,600,4150);ctx.fillStyle='#c2ae86';ctx.fillRect(67,-4000,586,4150);for(let j=0;j<1450;j++){const x=70+((j*137)%580),y=130-((j*239)%4120);ctx.fillStyle=j%3?'#d3bc8c':'#998363';ctx.fillRect(x,y,j%4+1,1)}
 ctx.strokeStyle='#f3dfaf55';ctx.lineWidth=2;ctx.setLineDash([13,20]);for(let i=1;i<6;i++){ctx.beginPath();ctx.moveTo(60+i*100,150);ctx.lineTo(60+i*100,-4000);ctx.stroke()}ctx.setLineDash([]);
 stages.forEach((s,i)=>{const y=-(i+1)*500;gate(y,s.gates[0],true,t);gate(y,s.gates[1],false,t);ctx.fillStyle='#253340';ctx.fillRect(280,y-135,160,28);ctx.fillStyle='#eadbb4';ctx.textAlign='center';ctx.font='14px system-ui';ctx.fillText('ЭТАП '+(i+1),360,y-115);if(i===1){ctx.fillStyle='#b98b5877';for(let n=0;n<7;n++){ctx.beginPath();ctx.ellipse(125+n*75,y+250+Math.sin(t/1300+n)*20,65,25,0,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#74583c';ctx.fillRect(170,y+350,50,12);ctx.fillRect(490,y+280,35,12)}if(i===3){ctx.fillStyle='#9f8964';ctx.fillRect(275,y+300,170,75)}});
 for(let i=0;i<24;i++){ctx.fillStyle=i%2?'#e9dabb':'#273240';ctx.fillRect(60+i*25,-2130,25,20);ctx.fillStyle=i%2?'#273240':'#e9dabb';ctx.fillRect(60+i*25,-2110,25,20)}
 person(610,-2240,'#75568e',t,finished);ctx.fillStyle='#fff0cd';ctx.font='16px system-ui';ctx.textAlign='center';ctx.fillText('Арвен Бран',595,-2280);person(746,-620,'#cc9c48',t,finished);person(24,-1820,'#6999a5',t,finished);ctx.font='11px system-ui';ctx.fillText('Золотая подкова',735,-657);
 const x=60+(lane-.5)*100,y=-pos;ctx.save();ctx.translate(x,y);ctx.fillStyle='#44362a55';ctx.beginPath();ctx.ellipse(0,28,44,60,0,0,Math.PI*2);ctx.fill();const key=fx&&t-fx.start<fx.duration?fx.key:anim?(selected.ability==='flight'?'flight':'gallop'):'idle';KaraAnimator.draw(ctx,{key,time:t,progress:anim?Math.min(.99,(t-anim.start)/anim.duration):.5,width:90,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches});ctx.restore();if(fx&&t-fx.start<fx.duration)KaraAnimator.effects(ctx,fx.key,{x,y,angle:0},t,(t-fx.start)/fx.duration);ctx.restore();requestAnimationFrame(draw)}
render();requestAnimationFrame(draw);
window.KaraTraining={stages,actions,abilities,gates,get state(){return{stage,hp,temp,charges:{...charges},lane,pos,finished,busy,phase}},reset};
})();
